components/supermarket/common/global-var:
{{#if theme_settings.csspreload}}
    {{#if settings.request.is_crawler}}
        {{assignVar 'isCrawlerAndSpeedTestMode' 1}}
    {{/if}}
{{/if}}
{{assignVar 'productCardImageSizeAttrs' (get 'string' (concat 'width=' (join (split theme_settings.productgallery_size 'x') ' height=')))}}
{{assignVar 'categoryImageSizeAttrs' (get 'string' (concat 'width=' (join (split theme_settings.categorythumb_size 'x') ' height=')))}}

components/common/header/og:
{{#contains head.meta_tags "og:image"}}
{{else}}
    {{#if page_type '==' 'category'}}
        {{#if category.image}}
            <meta property="og:image" content="{{getImage category.image 'category_size'}}" />
        {{/if}}
    {{else if page_type '==' 'brand'}}
        {{#if brand.image}}
            <meta property="og:image" content="{{getImage brand.image 'brand_main_size'}}" />
        {{/if}}
    {{/if}}
{{/contains}}

components/common/footer:
{{#or banners.bottom theme_settings.instantload}}
{{#if settings.data_tag_enabled}}
<div class="banners--bottom" data-banner-location="bottom">
    <div class="container">
        {{#each (limit banners.bottom_metadata 1)}}
        <div class="banner" data-event-type="promotion" data-entity-id="{{this.id}}" data-name="{{this.banner-name}}"
            data-position="{{this.location}}" data-name="{{this.banner-name}}">
            <div data-event-type="promotion-click">
                {{{this.content}}}
            </div>
        </div>
        {{/each}}
    </div>
</div>
{{else}}
<div class="banners--bottom" data-banner-location="bottom">
    <div class="container">
        <div class="banner">
            {{{limit banners.bottom 1}}}
        </div>
    </div>
</div>
{{/if}}
{{/or}}

{{{region name="footer_before"}}}
{{{region name="footer_before--global"}}}

<footer class="footer" role="contentinfo">
    <h2 class="is-srOnly">{{lang 'footer.footer_start'}}</h2>

    {{{region name="footer_top--global"}}}
    <section class="footer-info">
        <div class="container ">
            <div class="footer-info--list">
                {{#if theme_settings.footer_show_contactInfo}}
                    <article class="footer-info--contact-us">
                        {{#if theme_settings.footer_contactInfo_heading}}
                            <h3 class="footer-info-heading">
                                {{theme_settings.footer_contactInfo_heading}}
                            </h3>
                        {{/if}}
                        <div class="footer-info--item">
                            <svg class="icon">
                                <use href="#icon-location"></use>
                            </svg>
                            {{settings.address}}
                        </div>
                        {{#if settings.phone_number}}
                            <div class="footer-info--item">
                                <a  href="tel:{{settings.phone_number}}" title="{{lang 'header.call_us' phone_number=settings.phone_number}}">
                                    <svg class="icon">
                                        <use href="#icon-phone3"></use>
                                    </svg>
                                    {{settings.phone_number}}
                                </a>
                            </div>
                        {{/if}}
                        {{#if theme_settings.footer_email '!==' ""}}
                            <div class="footer-info--item">
                                <a href=mailto:{{theme_settings.footer_email}} title="{{theme_settings.footer_email}}">
                                    <svg class="icon">
                                        <use href="#icon-email"></use>
                                    </svg>
                                    {{theme_settings.footer_email}}
                                </a>
                            </div>
                        {{/if}}
                        {{#if theme_settings.footer_whatsapp '!==' ""}}
                            <div class="footer-info--item">
                                <a href=https://wa.me/{{theme_settings.footer_whatsapp}} title="{{theme_settings.footer_whatsapp}}">
                                    <svg class="icon">
                                        <use href="#icon-whatsapp"></use>
                                    </svg>
                                    {{theme_settings.footer_whatsapp}}
                                </a>
                            </div>
                        {{/if}}
                        {{#if theme_settings.social_icon_placement_bottom}}
                            {{> components/common/social-links}}
                        {{/if}}
                        {{{region name="footer_contact--global"}}}
                    </article>
                {{/if}}

                <div class="footer-info--wrapper">
                    {{#if theme_settings.footer_cs1}}
                    <article class="footer-info--col" data-dinosaur-footer-collapsible>
                        {{#if theme_settings.footer_cs1_title}}
                        <h3 class="footer-info-heading">
                            <a href="#" aria-expanded="false" data-dinosaur-footer-collapsible-handler>
                                {{theme_settings.footer_cs1_title}}
                                {{> components/common/footer-toggle-icon}}
                            </a>
                        </h3>
                        {{/if}}
                        <div class="_wrapper {{#unless theme_settings.footer_cs1_title}}is-open{{/unless}}" aria-hidden="true" data-dinosaur-footer-collapsible-content>
                            <ul class="footer-info-list">
                                {{{region name="footer_cs1--global"}}}
                            </ul>
                        </div>
                    </article>
                    {{/if}}

                    {{#if theme_settings.footer_show_pages '>' -1}}
                        <article class="footer-info--col" data-dinosaur-footer-collapsible>
                            {{#if theme_settings.footer_pages_heading}}
                                <h3 class="footer-info-heading">
                                    <a href="#" aria-expanded="false" data-dinosaur-footer-collapsible-handler>
                                        {{theme_settings.footer_pages_heading}}
                                        {{> components/common/footer-toggle-icon}}
                                    </a>
                                </h3>
                            {{/if}}
                            <div class="_wrapper {{#unless theme_settings.footer_pages_heading}}is-open{{/unless}}" aria-hidden="true" data-dinosaur-footer-collapsible-content>
                                {{#if theme_settings.footer_show_pages '>' 0}}
                                    <ul class="footer-info-list">
                                        {{#each (limit pages theme_settings.footer_show_pages)}}
                                            <li>
                                                <a href="{{url}}">{{name}}</a>
                                            </li>
                                        {{/each}}
                                        {{#if theme_settings.footer_show_pages '>' pages.length}}
                                            <li>
                                                <a href="{{urls.sitemap}}">{{lang 'sitemap.page_title'}}</a>
                                            </li>
                                        {{/if}}
                                    </ul>
                                {{/if}}
                                {{{region name="footer_below_col4--global"}}}
                            </div>
                        </article>
                    {{/if}}

                    {{#if theme_settings.footer_show_categories '>' -1}}
                        <article class="footer-info--col" data-dinosaur-footer-collapsible>
                            {{#if theme_settings.footer_categories_heading}}
                                <h3 class="footer-info-heading">
                                    <a href="#" aria-expanded="false" data-dinosaur-footer-collapsible-handler>
                                        {{theme_settings.footer_categories_heading}}
                                        {{> components/common/footer-toggle-icon}}
                                    </a>
                                </h3>
                            {{/if}}
                            <div class="_wrapper {{#unless theme_settings.footer_categories_heading}}is-open{{/unless}}" aria-hidden="true" data-dinosaur-footer-collapsible-content>
                                {{#if theme_settings.footer_show_categories '>' 0}}
                                <ul class="footer-info-list">
                                    {{#each (limit categories theme_settings.footer_show_categories)}}
                                    <li>
                                        <a href="{{url}}">{{name}}</a>
                                    </li>
                                    {{/each}}
                                </ul>
                                {{/if}}
                                {{{region name="footer_below_col2--global"}}}
                            </div>
                        </article>
                    {{/if}}

                    {{#if theme_settings.footer_shop_by_brand '>' -1}}
                        <article class="footer-info--col" data-dinosaur-footer-collapsible>
                            {{#if theme_settings.footer_brands_heading}}
                            <h3 class="footer-info-heading">
                                <a href="#" aria-expanded="false" data-dinosaur-footer-collapsible-handler>
                                    {{theme_settings.footer_brands_heading}}
                                    {{> components/common/footer-toggle-icon}}
                                </a>
                            </h3>
                            {{/if}}
                            <div class="_wrapper {{#unless theme_settings.footer_brands_heading}}is-open{{/unless}}" aria-hidden="true" data-dinosaur-footer-collapsible-content>
                                {{#if theme_settings.footer_shop_by_brand '>' 0}}
                                <ul class="footer-info-list">
                                    {{#each (limit shop_by_brand theme_settings.footer_shop_by_brand)}}
                                    <li>
                                        <a href="{{url}}">{{name}}</a>
                                    </li>
                                    {{/each}}
                                    <li><a href="{{urls.brands}}">{{lang 'common.view_all'}}</a></li>
                                </ul>
                                {{/if}}
                                {{{region name="footer_below_col3--global"}}}
                            </div>
                        </article>
                    {{/if}}

                    {{#if theme_settings.footer_cs2}}
                    <article class="footer-info--col" data-dinosaur-footer-collapsible>
                        {{#if theme_settings.footer_cs2_title}}
                        <h3 class="footer-info-heading">
                            <a href="#" aria-expanded="false" data-dinosaur-footer-collapsible-handler>
                                {{theme_settings.footer_cs2_title}}
                                {{> components/common/footer-toggle-icon}}
                            </a>
                        </h3>
                        {{/if}}
                        <div class="_wrapper {{#unless theme_settings.footer_cs2_title}}is-open{{/unless}}" aria-hidden="true" data-dinosaur-footer-collapsible-content>
                            <ul class="footer-info-list">
                                {{{region name="footer_cs5--global"}}}
                            </ul>
                        </div>
                        </article>
                    {{/if}}
                </div>

                {{#and settings.show_newsletter_box theme_settings.footer_show_newsletter}}
                    {{#if settings.show_newsletter_box}}
                        {{> components/beautify/section-home-newsletter}}
                    {{/if}}
                {{/and}}
            </div>
            {{#if theme_settings.footer_show_contactInfo '!==' true}}
            {{#if theme_settings.social_icon_placement_bottom}}
            {{> components/common/social-links}}
            {{/if}}
            {{/if}}
        </div>
    </section>
    {{{region name="footer_below_columns--global"}}}
    <div class="footer-below">
        <div class="container">
            <div class="footer-copyright">
                <div class="beautify__abovePoweredBy">
                    {{{region name="footer_above_powerby--global"}}}
                </div>
                <div class="powered-by">
                    <div class="_col">
                        {{#if theme_settings.show_copyright_footer}}
                        <p class="powered-by-text _col-copyright-footer">
                            &copy; <span id="copyright_year"></span> {{settings.store_name}}.
                            <script nonce="{{nonce}}">
                                document.getElementById("copyright_year").innerHTML = new Date().getFullYear();
                            </script>
                        </p>
                        {{/if}}
                        {{#if theme_settings.show_powered_by}}
                        <p class="powered-by-text _col-powered-by">
                            {{lang 'footer.powered_by'}}
                            <a href="http://bigcommerce.com" rel="nofollow">BigCommerce.</a>
                            Theme Designed By
                            <a href="https://papathemes.com" rel="nofollow">Papathemes.</a>
                        </p>
                        {{/if}}
                        {{{region name="footer_powered_by--global"}}}
                    </div>
                    {{{region name="footer_copyright--global"}}}
                </div>
            </div>
            <div class="footer-payments">
                {{> components/common/payment-icons}}
                {{> components/beautify/footer-icons}}
            </div>
        </div>
    </div>
</footer>
{{{region name="footer_bottom--global"}}}
{{#if settings.show_newsletter_box}}
{{#if theme_settings.nl_popup_show '===' 'home'}}
{{#if page_type '===' 'default'}}
{{> components/papathemes/newsletter/modal}}
{{/if}}
{{else if theme_settings.nl_popup_show '===' 'all'}}
{{> components/papathemes/newsletter/modal}}
{{/if}}
{{/if}}

components/common/header/logo:
{{#if template_file '===' 'pages/home'}}
<h1 class="header-logo{{#if settings.store_logo.image}} _isImg{{/if}}">
    {{> components/common/store-logo}}
</h1>
{{else}}
<div class="header-logo{{#if settings.store_logo.image}} _isImg{{/if}}">
    {{> components/common/store-logo}}
</div>
{{/if}}

components/papathemes/sections/section:
{{#if section '===' '-'}}

{{else if section '===' 'slideshow'}}
    {{#if carousel}}
        {{> components/carousel}}
    {{/if}}

{{else if section '===' 'blog_recent'}}
    {{#if theme_settings.homepage_blog_posts_count '>' 0}}
    {{> components/beautify/recent-blog posts=(limit blog.recent_posts theme_settings.homepage_blog_posts_count) index=index}}
    {{/if}}

{{else if section '===' 'top_categories'}}
    {{> components/beautify/top-categories index=index}}

{{else if section '===' 'new_products'}}
    {{#if products.new}}
        <div class="beautify__section dinosaur__productView {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--newProducts beautify__section--displayType-{{theme_settings.product_new_type}}">
        <div class="container">
        {{> components/products/new
            products=products.new
            show_categories=theme_settings.product_new_cats
            region_name="home_above_new_products"
            display_type=theme_settings.product_new_type}}
        </div>
        </div>
    {{/if}}

{{else if section '===' 'featured_products'}}
    {{#if products.featured}}
        <div class="beautify__section dinosaur__productView {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--featuredProducts beautify__section--displayType-{{theme_settings.product_featured_type}}">
        <div class="container">
        {{> components/products/featured
            products=products.featured
            region_name="home_above_featured_products"
            display_type=theme_settings.product_featured_type}}
        </div>
        </div>
    {{/if}}
{{else if section '===' 'popular_products'}}
    {{#if products.top_sellers}}
        <div class="beautify__section dinosaur__productView {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--topProducts beautify__section--displayType-{{theme_settings.product_top_type}}">
        <div class="container">
        {{> components/products/top
            products=products.top_sellers
            show_categories=theme_settings.product_top_cats
            region_name="home_above_top_products"
            display_type=theme_settings.product_top_type}}
        </div>
        </div>
    {{/if}}

{{else if section '===' 'recentviewed'}}
    <div class="beautify__section dinosaur__productView {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--recentlyViewedProducts beautify__section--displayType-{{theme_settings.product_recentviewed_type}}">
    <div class="container">
    {{> components/products/recentviewed
        index=index
        region_name="home_above_recentviewed_products"
        display_type=theme_settings.product_recentviewed_type}}
    </div>
    </div>

{{else if section '===' 'spt'}}
    {{#or theme_settings.spt_show_featured theme_settings.spt_show_top theme_settings.spt_show_new}}
        {{#or theme_settings.spt_init_count theme_settings.spt_lazy_count}}
            <div class="beautify__section {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--specialProductsTabs">
            <div class="container">
                {{> components/papathemes/special-products-tabs/section}}
            </div>
            </div>
        {{/or}}
    {{/or}}

{{else if section '===' 'pbcst'}}
    {{#if theme_settings.pbcst_catIDs}}
        {{inject 'haspbcst' true}}
        <div class="beautify__section {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--pbcst">
            <div class="container">
                <div class="papathemes-pbcst"
                    data-pbcst-group="{{theme_settings.pbcst_catIDs}}"
                    data-sort="{{theme_settings.pbcst_active}}"
                    data-limit="{{theme_settings.pbcst_products}}"
                    {{#if theme_settings.pbcst_lazy}}data-lazy{{/if}}>
                    {{#if theme_settings.pbcst_showBanner}}
                        {{#each (split theme_settings.pbcst_catIDs ',')}}
                            <div data-pbcst-widget-region="{{@index}}">{{{region name=(concat "pbcst_" @index)}}}</div>
                        {{/each}}
                    {{/if}}
                    {{#each (split theme_settings.pbcst_catIDs ',')}}
                        <div data-pbcst-widget-region="below_{{@index}}">{{{region name=(concat "pbcst_below_" @index)}}}</div>
                    {{/each}}
                </div>
            </div>
        </div>
    {{else if theme_settings.pbcst_count '>' 0}}
        {{inject 'haspbcst' true}}
        <div class="beautify__section {{#if index}}beautify__section--index{{index}}{{/if}} beautify__section--pbcst">
            <div class="container">
                <div class="papathemes-pbcst"
                    data-pbcst-group="{{join (pluck (limit categories theme_settings.pbcst_count) 'id') ','}}"
                    data-sort="{{theme_settings.pbcst_active}}"
                    data-limit="{{theme_settings.pbcst_products}}"
                    {{#if theme_settings.pbcst_lazy}}data-lazy{{/if}}>
                    {{#if theme_settings.pbcst_showBanner}}
                        {{#each (limit categories theme_settings.pbcst_count)}}
                            <div data-pbcst-widget-region="{{@index}}">{{{region name=(concat "pbcst_" @index)}}}</div>
                        {{/each}}
                    {{/if}}
                    {{#each (limit categories theme_settings.pbcst_count)}}
                        <div data-pbcst-widget-region="below_{{@index}}">{{{region name=(concat "pbcst_below_" @index)}}}</div>
                    {{/each}}
                </div>
            </div>
        </div>
    {{/if}}
{{else if section '===' 'featured_brands'}}
    {{#if shop_by_brand.length '>' 0}}
            <div id="dinosaur__featuredBrands" class="beautify__section dinosaur__featuredBrands {{#if index}}beautify__section--index{{index}}{{/if}} productCarousel--responsiveCol blaze-slider"
                {{#if settings.data_tag_enabled}} data-list-name="{{list}}"{{/if}}
                data-blaze-slider='{
                    "all": {
                        "autoplayInterval": 5000,
                        "stopAutoplayOnInteraction": true,
                        "transitionDuration": 500,
                        "slidesToShow": 6,
                        "slidesToScroll": 6,
                        "slideGap": "15px",
                        "loop": true
                    },
                    "(max-width: 1260px)": {
                        "slidesToShow": 5,
                        "slidesToScroll": 5
                    },
                    "(max-width: 800px)": {
                        "slidesToShow": 3.2,
                        "slidesToScroll": 3,
                        "slideGap": "10px"
                    },
                    "(max-width: 550px)": {
                        "slidesToShow": 2.2,
                        "slidesToScroll": 2
                    }
                }'
            >
                <div class="container">
                    {{#if theme_settings.featured_brands_heading}}
                        <h2 class="page-heading">{{theme_settings.featured_brands_heading}}</h2>
                    {{/if}}
                        <div class="blaze-container">
                            <div class="blaze-track-container">
                                <div class="blaze-track">
                                    {{#each shop_by_brand}}
                                        <a href="{{url}}" class='_brand-item' aria-label="{{name}}">
                                            <div class="_brand-img-wrapper" data-brand-id="{{id}}">
                                                <img  class='_brand-logo' alt="{{name}}">
                                                <div class='_brand-text'>
                                                    <span>{{name}}</span>
                                                </div>
                                            </div>
                                        </a>
                                    {{/each}}
                                </div>
                            </div>
                            <div class="blaze-pagination"></div>
                        </div>
                    </div>
            </div>
    {{/if}}

{{else if section '===' 'newsletter'}}
    {{#if settings.show_newsletter_box}}
        {{> components/beautify/section-home-newsletter}}
    {{/if}}
{{/if}}

components/dinosaur/left-sidebar/section:
{{#if sb '===' 'popular_products'}}
    {{#if products.top_sellers}}
        <div class="dinosaur-left-sidebar">
            {{> components/dinosaur/products/top
                products=(limit products.top_sellers theme_settings.product_top_count)
                hide_heading=false
                show_categories=true
                region_name="home_left_sidebar_above_best_sellers"
                show_badges=true}}
            {{{region name="home_left_sidebar_below_best_sellers"}}}
        </div>
    {{/if}}
{{else if sb '===' 'new_products'}}
    {{#if products.new}}
        <div class="dinosaur-left-sidebar">
            {{> components/dinosaur/products/new
                products=(limit products.new theme_settings.product_new_count)
                hide_heading=false
                show_categories=true
                region_name="home_left_sidebar_above_new_products"
                show_badges=true}}
            {{{region name="home_left_sidebar_below_new_products"}}}
        </div>
    {{/if}}
{{else if sb '===' 'featured_products'}}
    {{#if products.featured}}
        <div class="dinosaur-left-sidebar">
            {{> components/dinosaur/products/featured
                products=(limit products.featured theme_settings.product_featured_count)
                hide_heading=false
                show_categories=true
                region_name="home_left_sidebar_above_featured_products"
                show_badges=true}}
            {{{region name="home_left_sidebar_below_featured_products"}}}
        </div>
    {{/if}}
{{/if}}

components/common/social-links:
{{#if social_media}}
    <ul class="socialLinks--alt socialLinks {{#if style}}socialLinks--{{style}}{{/if}}">
        {{#each social_media}}
            {{#if display_name '==' 'twitter'}}
                <li class="socialLinks-item">
                    <a class="icon icon--{{display_name}}" href="{{url}}" target="_blank" rel="noopener" title="X">
                        <span class="aria-description--hidden">X</span>
                        <svg><use href="#icon-x" /></svg>
                    </a>
                </li>
            {{else}}
                <li class="socialLinks-item">
                    <a class="icon icon--{{display_name}}" href="{{url}}" target="_blank" rel="noopener" title="{{capitalize display_name}}">
                        <span class="aria-description--hidden">{{{capitalize display_name}}}</span>
                        <svg><use href="#icon-{{display_name}}" /></svg>
                    </a>
                </li>
            {{/if}}
        {{/each}}
    </ul>
{{/if}}

components/beautify/section-home-newslet:
{{#if settings.show_newsletter_box}}
    <article class="beautify__section {{#if index}}beautify__section--index{{index}}{{/if}} beautify__newsletter">
        <div class="container">
            {{#if theme_settings.newsletter_heading}}
                <h2 class="page-heading">{{theme_settings.newsletter_heading}}</h2>
            {{/if}}
            <form class="form" action="{{urls.subscribe.action}}" method="post">
                <fieldset class="form-fieldset">
                    <input type="hidden" name="action" value="subscribe">
                    <input type="hidden" name="nl_first_name" value="bc">
                    <input type="hidden" name="check" value="1">
                    <div class="form-field">
                        <label class="form-label is-srOnly" for="nl_email">{{lang 'common.email_address'}}</label>
                        <input class="form-input" id="nl_email" name="nl_email" type="email" value="{{customer.email}}" placeholder="{{lang 'newsletter.email_placeholder'}}">
                        <button class="button button-primary" type="submit" aria-label="{{lang 'newsletter.subscribe'}}"><svg class="icon"><use href="#icon-arrow-submit"/></svg></button>
                    </div>
                </fieldset>
            </form>
            {{#if settings.show_newsletter_summary}}
                {{#if settings.newsletter_summary}}
                    <p class="page-desc">{{{settings.newsletter_summary}}}</p>
                {{else if in_development}}
                    <p class="page-desc">Sign up for our newsletter and get the latest updates on new products and upcoming sales</p>
                {{/if}}
            {{/if}}
            {{{region name="footer_below_newsletters--global"}}}
        </div>
    </article>
{{/if}}

components/beautify/navigation-list:
{{#if children}}
<a class="navPages-action has-subMenu u-hideMobile u-hideTablet {{#if menu_type '==' 'vertical'}}navPages-action--vertical{{/if}}" href="{{url}}"
    href="{{url}}"
    {{#if menu_type '!=' 'vertical'}}data-instantload{{/if}}
    {{#if id '==' category.id}}data-current-category{{/if}}
>{{name}}</a>
<a class="navPages-action-toggle" href="#" data-collapsible="navPages-{{#if page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{idSuffix}}">
    <span>{{name}}</span>
    <span class="_more"><span class="is-srOnly">{{lang 'common.nav_more'}}</span><svg class="icon"><use href="#icon-add"></use></svg></span>
    <span class="_less"><span class="is-srOnly">{{lang 'common.nav_back'}}</span><svg class="icon"><use href="#icon-remove"></use></svg></span>
</a>
<a class="navPages-action-toggle-desktop" href="#" data-collapsible="navPages-{{#if page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{idSuffix}}" title="{{lang 'common.nav_more'}}"><svg class="icon"><use href="#icon-caret-down"></use></svg></a>
<div class="navPage-subMenu
        {{#if menu_type '==' 'vertical'}}
            navPage-subMenu--vertical
        {{else if menu_type '==' 'standard'}}
            navPage-subMenu--standard
        {{else if menu_type '==' 'column'}}
            navPage-subMenu--column
        {{/if}}
    " id="navPages-{{#if page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{idSuffix}}">
    {{#if page_type '!==' 'page'}}
        <div class="navPage-subMenu-top">
            {{{region name=(concat (concat "navPages_" id) "_top--global")}}}
        </div>
    {{/if}}
    <div class="navPage-subMenu-middle">
        {{#if page_type '!==' 'page'}}
            {{{region name=(concat (concat "navPages_" id) "_left--global")}}}
        {{/if}}
        <ul class="navPage-subMenu-list">
            {{#each children}}
                <!-- {{incrementVar 'navWebPageCount'}} -->
                <li class="navPage-subMenu-item">
                    {{{region name=(concat (concat "navPages_" id) "_top--global")}}}
                    {{#if children}}
                        <a
                            class="navPage-subMenu-action has-subMenu"
                            href="{{url}}"
                            {{#if ../../menu_type '!=' 'vertical'}}data-instantload{{/if}}
                            {{#if id '==' ../../category.id}}data-current-category{{/if}}
                            >
                                <span>{{name}}</span>
                        </a>
                        <a href="#" class="_hideToggleFirst u-hidden"></a>
                        <a class="navPages-action-toggle" href="#"
                            data-collapsible="navPages-{{#if ../../page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{../../idSuffix}}">
                            <span>{{name}}</span>
                            <span class="_more"><span class="is-srOnly">{{lang 'common.nav_more'}}</span><svg class="icon"><use href="#icon-arrow-right"></use></svg></span>
                            <span class="_less"><span class="is-srOnly">{{lang 'common.nav_less'}}</span><svg class="icon"><use href="#icon-arrow-left"></use></svg></span>
                        </a>
                        <a class="navPages-action-toggle-desktop" tabindex="0" href="#" data-collapsible="navPages-{{#if ../../page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{../../idSuffix}}" title="{{lang 'common.nav_more'}}">
                            {{#if theme_settings.navPages_type '==' 'megamenu'}}
                                <span>{{name}}</span>
                            {{else}}
                                <svg class="icon"><use href="#icon-caret-down"></use></svg>
                            {{/if}}
                        </a>
                        <ul class="navPage-childList" id="navPages-{{#if ../../page_type '==' 'page'}}page-{{getVar 'navWebPageCount'}}{{/if}}{{id}}{{../../idSuffix}}">
                            {{#each children}}
                                <!-- {{incrementVar 'navWebPageCount'}} -->
                                <li class="navPage-childList-item">
                                    {{> components/beautify/navigation-list-child
                                            category_id=../../../category.id
                                            idSuffix=../../../idSuffix
                                            theme_settings=../../../theme_settings
                                            menu_type=../../../menu_type
                                            page_type=../../../page_type}}
                                </li>
                            {{/each}}
                            <li class="navPage-childList-item u-hideDesktop">
                                <a href="{{url}}" class="navPage-childList-action">{{lang 'common.view_all_products'}}</a>
                            </li>
                            <a href="#" class="_hideToggle u-hideDesktop"></a>
                            {{!--
                            <!--
                            {{#if ../../menu_type '==' 'mega'}}
                                <li class="navPage-childList-item">
                                    <a class="navPage-childList-action" href="{{url}}" data-instantload>{{lang 'common.view_all'}}</a>
                                </li>
                            {{/if}}
                            -->
                            --}}
                        </ul>
                    {{else}}
                        <a class="navPage-subMenu-action" href="{{url}}" data-instantload {{#if id '==' ../../category.id}}data-current-category{{/if}}>
                            <span>{{name}}</span>
                        </a>
                    {{/if}}
                    {{#if ../page_type '!==' 'page'}}
                        {{{region name=(concat (concat "navPages_" id) "_bottom--global")}}}
                    {{/if}}
                </li>
            {{/each}}
            <li class="navPage-subMenu-item u-hideDesktop">
                <a href="{{url}}" class="navPage-subMenu-action">
                    <span>{{lang 'common.view_all_products'}}</span>
                </a>
            </li>
        </ul>
        {{#if page_type '!==' 'page'}}
            {{{region name=(concat (concat "navPages_" id) "_right--global")}}}
        {{/if}}
    </div>
    {{#if page_type '!==' 'page'}}
        <div class="navPage-subMenu-bottom">
            {{{region name=(concat (concat "navPages_" id) "_bottom--global")}}}
        </div>
    {{/if}}
</div>
{{else}}
<a class="navPages-action" href="{{url}}" data-instantload {{#if id '==' category.id}}data-current-category{{/if}}>{{name}}</a>
{{/if}}

