        "all": {
            "enableAutoplay": false,
            "autoplayInterval": 5000,
            "stopAutoplayOnInteraction": true,
            "transitionDuration": 500,
            "slidesToShow": 6,
            "slidesToScroll": 6,
            "slideGap": "30px",
            "loop": true,
            "pagination": true
        },
        "(max-width: 1260px)": {
            "slidesToShow": 4,
            "slidesToScroll": 4
        },
        "(max-width: 800px)": {
            "slidesToShow": 4,
            "slidesToScroll": 3,
            "slideGap": "16px"
        },
        "(max-width: 550px)": {
            "slidesToShow": 3,
            "slidesToScroll": 2,
            "slideGap": "8px"
        }
    }'
