    <h2 class="page-heading">{{theme_settings.product_featured_heading}}</h2>
    {{/unless}}
</span>

{{#if show_categories}}
    <div class="navProducts-rootMenu-list">
        <ul class="navProducts-list">
            {{#each categories}}
            <li class="navProducts-item">
                <a class="navPages-action" href="{{url}}?sort=featured" data-instantload>{{name}}</a>
            </li>
            {{/each}}
        </ul>
    </div>
{{/if}}

{{#if region_name}}
    {{{region name=region_name}}}
{{/if}}

<ul class="productGrid productGrid--responsiveCol" data-product-type="featured" id="featured-products{{#if index}}_index{{index}}{{/if}}" {{#if settings.data_tag_enabled}} data-list-name="Featured Products"{{/if}}>
    {{#each products}}
        <li class="product" data-product-id="{{id}}">
            {{>components/products/card 
                show_badges=../show_badges
                show_compare=../theme_settings.card_show_compare
                show_rating=../settings.show_product_rating
                theme_settings=../theme_settings 
                settings=../settings 
                customer=../customer
                event="list" position=(add @index 1)}}
        </li>
    {{/each}}
</ul>

<div class="loading" style="display: none;display: block;"></div>
<div class="actionGroup">
    <a href="#" class="button button--small button--link loadMore" style="display: none;">
        {{lang 'common.load_more'}}<svg class="icon"><use href="#icon-circle-arrow-right"></use></svg></a>
    <a href="#" class="button button--small button--link collapse" style="display: none;">
        {{lang 'common.collapse'}}</a>
</div>

components/papathemes/special-products-t:
{{inject 'hasSpecialProductsTabs' true}}
<div class="papathemes-specialProductsTabs" data-special-products-tabs='{
    "initCount": "{{theme_settings.spt_init_count}}",
    "lazyCount": "{{theme_settings.spt_lazy_count}}",
    "showMore": {{json theme_settings.spt_more}},
    "type": "{{theme_settings.spt_type}}"
}'>
    <ul class="tabs" id="papathemes-specialProductsTabs-tabs" data-tab role="tablist">
        {{#if theme_settings.spt_show_new}}
            {{#or (unless theme_settings.spt_init_count) products.new}}
                <li class="tab{{#if theme_settings.spt_active_tab '===' 'new'}} is-active{{/if}}" role="presentation"><a class="tab-title" href="#tab-new-products" role="tab" tabindex="0" aria-selected="{{#if theme_settings.spt_active_tab '===' 'new'}}true{{else}}false{{/if}}" aria-controls="tab-new-products">{{lang 'products.new' }}</a></li>
            {{/or}}
        {{/if}}
        {{#if theme_settings.spt_show_featured}}
            {{#or (unless theme_settings.spt_init_count) products.featured}}
                <li class="tab{{#if theme_settings.spt_active_tab '===' 'featured'}} is-active{{/if}}" role="presentation"><a class="tab-title" href="#tab-featured-products" role="tab" tabindex="0" aria-selected="{{#if theme_settings.spt_active_tab '===' 'featured'}}true{{else}}false{{/if}}" aria-controls="tab-featured-products">{{lang 'products.featured' }}</a></li>
            {{/or}}
        {{/if}}
        {{#if theme_settings.spt_show_top}}
            {{#or (unless theme_settings.spt_init_count) products.top_sellers}}
                <li class="tab{{#if theme_settings.spt_active_tab '===' 'top'}} is-active{{/if}}" role="presentation"><a class="tab-title" href="#tab-bestselling-products" role="tab" tabindex="0" aria-selected="{{#if theme_settings.spt_active_tab '===' 'top'}}true{{else}}false{{/if}}" aria-controls="tab-bestselling-products">{{lang 'products.top' }}</a></li>
            {{/or}}
        {{/if}}
    </ul>
    <div class="tabs-contents">
        <section role="tabpanel" aria-hidden="{{#if theme_settings.spt_active_tab '===' 'new'}}false{{else}}true{{/if}}" class="tab-content{{#if theme_settings.spt_active_tab '===' 'new'}} is-active{{/if}}" id="tab-new-products" data-product-type="new">
            {{> components/products/new
                products=(limit products.new theme_settings.spt_init_count)
                hide_heading=true
                show_categories=theme_settings.spt_show_cats
                region_name="home_spt_above_new_products"
                display_type=theme_settings.spt_type}}
            {{#if theme_settings.spt_lazy_count}}
                <div class="papathemes-specialProductsTabs-viewportCheck" data-viewport-check="new"></div>
            {{/if}}
        </section>
        <section role="tabpanel" aria-hidden="{{#if theme_settings.spt_active_tab '===' 'featured'}}false{{else}}true{{/if}}" class="tab-content{{#if theme_settings.spt_active_tab '===' 'featured'}} is-active{{/if}}" id="tab-featured-products" data-product-type="featured">
            {{> components/products/featured
                products=(limit products.featured theme_settings.spt_init_count)
                hide_heading=true
                show_categories=theme_settings.spt_show_cats
                region_name="home_spt_above_featured_products"
                display_type=theme_settings.spt_type}}
            {{#if theme_settings.spt_lazy_count}}
                <div class="papathemes-specialProductsTabs-viewportCheck" data-viewport-check="featured"></div>
            {{/if}}
        </section>
        <section role="tabpanel" aria-hidden="{{#if theme_settings.spt_active_tab '===' 'top'}}false{{else}}true{{/if}}" class="tab-content{{#if theme_settings.spt_active_tab '===' 'top'}} is-active{{/if}}" id="tab-bestselling-products" data-product-type="top">
            {{> components/products/top
                products=(limit products.top_sellers theme_settings.spt_init_count)
                hide_heading=true
                show_categories=theme_settings.spt_show_cats
                region_name="home_spt_above_top_products"
                display_type=theme_settings.spt_type}}
            {{#if theme_settings.spt_lazy_count}}
                <div class="papathemes-specialProductsTabs-viewportCheck" data-viewport-check="top_sellers"></div>
            {{/if}}
        </section>
    </div>
    <div class="papathemes-specialProductsTabs-actionGroup">
        <a href="#" class="button button--small button--link loadMore" style="display:none">{{lang 'papathemes.pbcst.load_more'}}</a>
        <a href="#" class="button button--small button--link collapse" style="display:none">{{lang 'papathemes.pbcst.collapse'}}</a>
    </div>
</div>

components/products/list-item:
{{#if settings.data_tag_enabled}}
    <article class="listItem"
        data-event-type="{{event}}"
        data-entity-id="{{id}}"
        data-position="{{position}}"
        data-name="{{name}}"
        data-product-category="{{#each category}}{{#if @last}}{{this}}{{else}}{{this}}, {{/if}}{{/each}}"
        data-product-brand="{{brand.name}}"
        data-product-price="
            {{#or customer (unless settings.hide_price_from_guests)}}
                {{#if price.with_tax}}
                    {{price.with_tax.value}}
                {{else}}
                    {{price.without_tax.value}}
                {{/if}}
            {{else}}
                {{lang 'common.login_for_pricing'}}
            {{/or}}
        ">
{{else}}
    <article class="listItem" >
{{/if}}
    <figure class="listItem-figure">
        {{#or price.non_sale_price_with_tax price.non_sale_price_without_tax}}
            {{#if theme_settings.product_sale_badges '===' 'sash'}}
                <div class="sale-flag-sash">
                    <span class="sale-text">{{theme_settings.product_sale_label}}</span>
                </div>
            {{else if theme_settings.product_sale_badges '===' 'label'}}
                <div class="sale-flag-side">
                    <span class="sale-text">{{theme_settings.product_sale_label}}</span>
                </div>
            {{else if theme_settings.product_sale_badges '===' 'burst'}}
                <div class="starwrap">
                    <div class="sale-flag-star"></div>
                    <div class="sale-text-burst">{{theme_settings.product_sale_label}}</div>
                </div>
            {{/if}}
        {{/or}}
        {{#if theme_settings.product_custom_badges}}
            {{#each custom_fields}}
                {{#if name '===' '__badge'}}
                    <div class="sale-flag-side sale-flag-side--custom">
                        <span class="sale-text">{{{value}}}</span>
                    </div>
                {{/if}}
            {{/each}}
        {{/if}}
        <a href="{{url}}" {{#if settings.data_tag_enabled}} data-event-type="product-click" {{/if}}>
            {{> components/common/responsive-img
                image=image
                class="listItem-image"
                fallback_size=theme_settings.productgallery_size
                lazyload=theme_settings.lazyload_mode
                default_image=theme_settings.default_image_product
                otherAttributes=(getVar 'productCardImageSizeAttrs')
            }}
        </a>
    </figure>
    <div class="listItem-body">
        <div class="listItem-content">
            <div class="listItem-details">
                <h4 class="listItem-title">
                    <a href="{{url}}" {{#if settings.data_tag_enabled}} data-event-type="product-click" {{/if}}>{{name}}</a>
                </h4>
                {{#if brand.name}}
                <p class="listItem-brand">{{brand.name}}</p>
                {{/if}}
                {{#if price}}
                    <div class="listItem-price">
                        {{#or customer (unless settings.hide_price_from_guests)}}
                            {{> components/products/price price=price customer=customer}}
                        {{else}}
                            {{> components/common/login-for-pricing}}
                        {{/or}}
                    </div>
                {{/if}}
                {{#and rating show_rating}}
                    <p class="listItem-rating"><span class="rating--small">{{> components/products/ratings rating=rating}}</span></p>
                {{/and}}
                {{#if summary}}
                    <p>{{{summary}}}</p>
                {{/if}}
            </div>
            <div class="listItem-actions">
                <div class="listItem-buttons">
                {{#if show_cart_action}}
                {{#unless hide_add_to_cart}}
                    {{#if has_options}}
                        <a href="{{url}}" {{#if settings.data_tag_enabled}} data-event-type="product-click" {{/if}} class="button button--small button--primary{{#unless hide_product_quick_view}}{{#if theme_settings.show_product_quick_view}}{{#if theme_settings.ajax_add_to_cart}} quickview-alt{{/if}}{{/if}}{{/unless}}" data-product-id="{{id}}">{{lang "products.choose_options"}}</a>
                    {{else}}
                        {{#if out_of_stock_message }}
                        <a href="{{url}}" {{#if settings.data_tag_enabled}} data-event-type="product-click" {{/if}} class="button button--small button--primary">{{out_of_stock_message}}</a>
                        {{else if add_to_cart_url}}
                        <a href="{{add_to_cart_url}}" {{#if settings.data_tag_enabled}}{{#unless theme_settings.ajax_add_to_cart}} data-event-type="product-click"{{/unless}}{{/if}} class="button button--small button--primary"{{#if theme_settings.ajax_add_to_cart}} data-papathemes-cart-item-add{{/if}}>{{lang "products.add_to_cart"}}</a>
                        {{/if}}
                    {{/if}}
                {{/unless}}
                {{/if}}
                {{#if show_compare}}
                <a class="button button--small button--compare" href="#" data-compare-id="{{id}}">{{lang 'products.compare'}}</a>
                {{/if}}
                {{#unless hide_product_quick_view}}
                    {{#if theme_settings.show_product_quick_view}}
                        <a {{#if settings.data_tag_enabled}} data-event-type="product-click" {{/if}} class="button button--small quickview" data-product-id="{{id}}">{{lang 'products.quick_view'}}</a>
                    {{/if}}
                {{/unless}}
                </div>
            </div>
        </div>
    </div>
</article>

components/products/price:
{{! Supermarket: 
    Add class: price-was-label, price--main
}}
{{!-- There are 2 code paths for generating the PDP pricing HTML determined by the following #and condition. 
    If a 'price_range' exists then we generate all HTML in price-range.html, otherwise it is defined here. Both code
    paths generate the same HTML structure with some differences in whether that element is displayed by default (css styling).

    If you are making a change here or in price-range.html, you probably want to make that change in both files. --}}
    {{#and price.price_range (if theme_settings.price_ranges '==' true)}}
        {{> components/products/price-range price=price}}
    {{else}}
        <div class="price-section price-section--withTax price--withTax" {{#unless price.with_tax}}style="display: none;"{{/unless}}>
            <span class="price-label" {{#if price.non_sale_price_with_tax}}style="display: none;"{{/if}}>{{theme_settings.pdp-price-label}}</span>
            <span class="price-now-label" {{#unless price.non_sale_price_with_tax}}style="display: none;"{{/unless}}>{{theme_settings.pdp-sale-price-label}}</span>
            <span data-product-price-with-tax class="price price--withTax price--main{{#or price.rrp_with_tax price.non_sale_price_with_tax}} _hasSale{{/or}}">{{price.with_tax.formatted}}</span>
            {{#if price.without_tax}}
                <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
        <div class="price-section price-section--withTax non-sale-price--withTax" {{#unless price.non_sale_price_with_tax}}style="display: none;"{{/unless}}>
            <span class="price-was-label">{{theme_settings.pdp-non-sale-price-label}}</span>
            <span data-product-non-sale-price-with-tax class="price price--non-sale">{{price.non_sale_price_with_tax.formatted}}</span>
            {{#if price.without_tax}}
                <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
        {{#if theme_settings.show_rrp}}
            <div class="price-section price-section--withTax rrp-price--withTax" {{#unless price.rrp_with_tax}}style="display: none;"{{/unless}}>
                <span class="price-was-label">{{theme_settings.pdp-retail-price-label}}</span>
                <span data-product-rrp-price-with-tax class="price price--rrp">{{price.rrp_with_tax.formatted}}</span>
                {{#if price.without_tax}}
                    <abbr title="{{lang 'products.including_tax'}}">{{lang 'products.price_with_tax' tax_label=price.tax_label}}</abbr>
                {{/if}}
            </div>
        {{/if}}
        {{#and price.with_tax price.without_tax}}<div class="_br"></div>{{/and}}
        <div class="price-section price-section--withoutTax price--withoutTax" {{#unless price.without_tax}}style="display: none;"{{/unless}}>
            <span class="price-label" {{#if price.non_sale_price_without_tax}}style="display: none;"{{/if}}>{{theme_settings.pdp-price-label}}</span>
            <span class="price-now-label" {{#unless price.non_sale_price_without_tax}}style="display: none;"{{/unless}}>
                {{theme_settings.pdp-sale-price-label}}
            </span>
            <span data-product-price-without-tax class="price price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}} price--main {{#or price.rrp_without_tax price.non_sale_price_without_tax}} _hasSale{{/or}}">{{price.without_tax.formatted}}</span>
            {{#if price.with_tax}}
                <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
        <div class="price-section price-section--withoutTax non-sale-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.non_sale_price_without_tax}}style="display: none;"{{/unless}}>
            <span class="price-was-label">{{theme_settings.pdp-non-sale-price-label}}</span>
            <span data-product-non-sale-price-without-tax class="price price--non-sale">{{price.non_sale_price_without_tax.formatted}}</span>
            {{#if price.with_tax}}
                <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.tax_label}}</abbr>
            {{/if}}
        </div>
        {{#if theme_settings.show_rrp}}
            <div class="price-section price-section--withoutTax rrp-price--withoutTax{{#if price.with_tax}} price-section--minor{{/if}}" {{#unless price.rrp_without_tax}}style="display: none;"{{/unless}}>
                <span class="price-was-label">{{theme_settings.pdp-retail-price-label}}</span>
                <span data-product-rrp-price-without-tax class="price price--rrp"> {{price.rrp_without_tax.formatted}}</span>
                {{#if price.with_tax}}
                    <abbr title="{{lang 'products.excluding_tax'}}">{{lang 'products.price_without_tax' tax_label=price.tax_label}}</abbr>
                {{/if}}
            </div>
        {{/if}}
    {{/and}}

